def transform(grid):
    h, w = len(grid), len(grid[0])
    bars = [row[0] for row in grid
            if row[0] != 0 and all(v == row[0] for v in row)]
    seq = [c for c in bars if c != 9]

    # Group repeated colors together at the position of their last occurrence.
    grouped = []
    seen = set()
    for i, c in enumerate(seq):
        if c in seen:
            continue
        seen.add(c)
        if seq.count(c) > 1:
            if i == max(j for j, x in enumerate(seq) if x == c):
                grouped.extend([c] * seq.count(c))
        else:
            grouped.append(c)

    return [[grouped[i % len(grouped)]] * w for i in range(h)]
